INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'What is ''enzyme washing'' (e.g., cellulase treatment) commonly used for on denim/cotton garments?', '["Creating a soft, worn/faded look by controlled enzymatic breakdown of surface cellulose fibrils, an alternative to abrasive stone washing","Adding permanent bright new color to previously undyed fabric","Increasing the fabric''s stiffness and rigidity intentionally","Removing all fiber content, leaving only the finishing chemicals behind"]'::jsonb, 'Creating a soft, worn/faded look by controlled enzymatic breakdown of surface cellulose fibrils, an alternative to abrasive stone washing', 'Cellulase enzymes selectively attack and loosen surface cellulose micro-fibrils on cotton (especially indigo-dyed denim), creating a soft handle and faded, worn appearance — a gentler, more controllable alternative to traditional abrasive stone-washing with pumice stones.', 1, '{"enzyme-washing"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'Why might enzyme washing be preferred over traditional pumice stone-washing for denim finishing, from a process-control standpoint?', '["Enzyme action can be more precisely controlled (via time, temperature, enzyme concentration) and reduces mechanical damage/fabric loss compared to abrasive stones","Enzyme washing always takes much longer than stone washing with no other benefit","Enzyme washing cannot achieve any fading effect at all, unlike stone washing","Pumice stones chemically react with cotton in the same way enzymes do"]'::jsonb, 'Enzyme action can be more precisely controlled (via time, temperature, enzyme concentration) and reduces mechanical damage/fabric loss compared to abrasive stones', 'Enzyme treatments allow finer control over the degree of fading/softening (adjusting enzyme concentration, time, temperature) and cause less physical fabric damage/machine wear than tumbling with abrasive pumice stones, while still achieving a similar aesthetic effect.', 2, '{"enzyme-vs-stone-washing"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'What is ''garment dyeing'' as opposed to piece (fabric) dyeing or yarn dyeing?', '["Dyeing the fully constructed/sewn garment as a complete unit, rather than dyeing loose fiber, yarn, or flat fabric before cutting and sewing","A method that only applies dye to buttons and zippers, not the fabric itself","A synonym for fabric printing with no relation to actual dyeing","A process that always happens before the garment is cut and sewn"]'::jsonb, 'Dyeing the fully constructed/sewn garment as a complete unit, rather than dyeing loose fiber, yarn, or flat fabric before cutting and sewing', 'Garment dyeing colors the finished, sewn garment as a whole unit (after cutting/sewing), differing from piece dyeing (flat fabric before cutting) or yarn dyeing (before weaving/knitting) — offering flexibility for quick-response color decisions and unique washed/vintage garment effects.', 1, '{"garment-dyeing"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'What is a key production planning ADVANTAGE of garment dyeing over piece dyeing for fashion brands needing to react quickly to trend/color demand?', '["Garments can be cut and sewn in an undyed/grey state in advance, with the final color decision and dyeing delayed until closer to the actual order/trend demand","Garment dyeing always takes far longer than piece dyeing, reducing responsiveness","Garment dyeing requires committing to a color choice much earlier in production than piece dyeing","There is no planning-related advantage; the two methods are operationally identical"]'::jsonb, 'Garments can be cut and sewn in an undyed/grey state in advance, with the final color decision and dyeing delayed until closer to the actual order/trend demand', 'By postponing the final dyeing step until after cut-and-sew, brands can hold undyed inventory and make late-stage color decisions closer to actual demand/trend signals, improving responsiveness and reducing the risk of overproducing an unpopular color in piece-dyed fabric.', 2, '{"garment-dyeing-advantage"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'What is a technical CHALLENGE specific to garment dyeing that piece dyeing generally avoids?', '["Different components of a garment (e.g., body fabric, pocket lining, thread, trims) may take up dye differently, risking visible shade mismatches within the same garment","Garment dyeing never has any technical challenges compared to piece dyeing","Garment dyeing always produces perfectly even color with zero risk of mismatch, unlike piece dyeing","Piece dyeing has the exact same component-shade-matching risk as garment dyeing"]'::jsonb, 'Different components of a garment (e.g., body fabric, pocket lining, thread, trims) may take up dye differently, risking visible shade mismatches within the same garment', 'A finished garment may combine different fabrics, sewing threads, and trims that were made from different fiber types or lots; when dyed together as one garment, these different components can take up dye differently (different shade/depth), creating a visible mismatch that wouldn''t occur when dyeing a single, uniform piece of fabric.', 2, '{"garment-dyeing-challenge"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'What is the purpose of testing a fabric''s ''pH value'' as part of finished-goods quality/compliance testing (e.g., Oeko-Tex)?', '["To ensure the fabric''s residual pH is close to skin-neutral, since a strongly acidic or alkaline finished fabric could cause skin irritation on direct contact","To measure the exact dye recipe used during production","To determine the fabric''s final color shade only","pH testing has no relevance to skin-contact textile products at all"]'::jsonb, 'To ensure the fabric''s residual pH is close to skin-neutral, since a strongly acidic or alkaline finished fabric could cause skin irritation on direct contact', 'Residual alkalinity/acidity from processing chemicals (scouring, bleaching, dyeing) can remain on fabric if not properly neutralized/rinsed; skin-contact textile standards check that finished fabric pH falls within a skin-safe range to avoid potential irritation.', 1, '{"ph-testing","compliance"}'::text[]);
